/**
 * Format a percentage value with a sign prefix (+/-) and configurable decimal digits.
 * Returns null when the input is null (e.g. prior period has no data → can't compute delta).
 */
export function formatPercent(value: number | null, digits = 1): string | null {
  if (value === null) return null
  const prefix = value > 0 ? '+' : ''
  return `${prefix}${value.toFixed(digits)}%`
}

/**
 * Compute a compare delta as a percentage.
 * Returns null when prior is 0 (division by zero) or null.
 */
export function computeDelta(current: number, prior: number | null | undefined): number | null {
  if (prior == null || prior === 0) return null
  return ((current - prior) / prior) * 100
}

