import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  group_by: z.enum(['day', 'week', 'month']).default('day'),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface RevenueKpis {
  totalRevenue: number
  avgSessionValue: number
  depositsCollected: number
  tipsCollected: number
  sessionsCompleted: number
}

interface RevenueTimeline {
  period: string
  revenue: number
  deposits: number
  tips: number
  count: number
}

async function fetchRevenueData(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string | undefined,
  to: string | undefined,
  groupBy: 'day' | 'week' | 'month',
): Promise<{ timeline: RevenueTimeline[]; kpis: RevenueKpis }> {
  let query = supabase
    .from('bookings')
    .select('id, scheduled_at, price_cents, deposit_cents, tip_cents, status')
    .eq('studio_id', studioId)
    .eq('status', 'completed')
    .order('scheduled_at', { ascending: true })

  if (from) query = query.gte('scheduled_at', from)
  if (to) query = query.lte('scheduled_at', to)

  const { data: bookings, error } = await query
  if (error) throw error

  const grouped = (bookings ?? []).reduce<Record<string, RevenueTimeline>>((acc, b) => {
    const d = new Date(b.scheduled_at)
    let key: string
    if (groupBy === 'month') {
      key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
    } else if (groupBy === 'week') {
      const startOfYear = new Date(d.getFullYear(), 0, 1)
      const week = Math.ceil(((d.getTime() - startOfYear.getTime()) / 86400000 + startOfYear.getDay() + 1) / 7)
      key = `${d.getFullYear()}-W${String(week).padStart(2, '0')}`
    } else {
      key = d.toISOString().slice(0, 10)
    }

    const rev = b.price_cents ?? 0
    const tips = b.tip_cents ?? 0
    const dep = b.deposit_cents ?? 0
    if (!acc[key]) acc[key] = { period: key, revenue: 0, deposits: 0, tips: 0, count: 0 }
    const entry = acc[key]!
    entry.revenue += rev
    entry.deposits += dep
    entry.tips += tips
    entry.count++
    return acc
  }, {})

  const timeline = Object.values(grouped).sort((a, b) => a.period.localeCompare(b.period))

  const totalRevenue = timeline.reduce((s, r) => s + r.revenue, 0)
  const totalDeposits = timeline.reduce((s, r) => s + r.deposits, 0)
  const totalTips = timeline.reduce((s, r) => s + r.tips, 0)
  const sessionCount = bookings?.length ?? 0
  const avgSessionValue = sessionCount > 0 ? Math.round(totalRevenue / sessionCount) : 0

  return {
    timeline,
    kpis: {
      totalRevenue,
      avgSessionValue,
      depositsCollected: totalDeposits,
      tipsCollected: totalTips,
      sessionsCompleted: sessionCount,
    },
  }
}

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to, group_by, compare } = parsed.data
  const supabase = await createClient()

  try {
    const current = await fetchRevenueData(supabase, auth.studioId, from, to, group_by)

    if (compare !== '1' || !from || !to) {
      return Response.json({ current })
    }

    const prior = priorRange({ from, to })
    const priorData = await fetchRevenueData(supabase, auth.studioId, prior.from, prior.to, group_by)

    return Response.json({ current, prior: priorData })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'revenue report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface ClientsKpis {
  totalClients: number
  newClients: number
  returningClients: number
  inactiveClients: number
  avgLtv: number
  retentionRate: number
}

async function fetchClientsData(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string | undefined,
  to: string | undefined,
): Promise<ClientsKpis> {
  const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()

  // All-time clients + completed bookings (filtered by period if range given)
  const [allClients, bookings] = await Promise.all([
    supabase.from('clients').select('id, created_at').eq('studio_id', studioId),
    supabase.from('bookings')
      .select('client_id, studio_id, scheduled_at, price_cents, deposit_cents')
      .eq('studio_id', studioId)
      .eq('status', 'completed')
      .order('scheduled_at', { ascending: true })
      .then((r) => {
        if (!r.data) return r
        let filtered = r.data
        if (from) filtered = filtered.filter((b) => b.scheduled_at >= from)
        if (to) filtered = filtered.filter((b) => b.scheduled_at <= to)
        return { ...r, data: filtered }
      }),
  ])

  if (allClients.error) throw allClients.error
  if (bookings.error) throw bookings.error

  // Count clients created inside the date window (for "new this period")
  const clientsInWindow = (allClients.data ?? []).filter((c) => {
    if (from && c.created_at < from) return false
    if (to && c.created_at > to) return false
    return true
  })

  const totalClients = clientsInWindow.length

  const clientSpend = new Map<string, number>()
  const clientLastVisit = new Map<string, string>()

  for (const b of bookings.data ?? []) {
    if (!b.client_id) continue
    const rev = (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
    clientSpend.set(b.client_id, (clientSpend.get(b.client_id) ?? 0) + rev)
    const prev = clientLastVisit.get(b.client_id)
    if (!prev || b.scheduled_at > prev) clientLastVisit.set(b.client_id, b.scheduled_at)
  }

  const returningClients = Array.from(clientSpend.entries()).filter(([id]) => {
    const sessions = (bookings.data ?? []).filter((b) => b.client_id === id).length
    return sessions > 1
  }).length

  const newClients = totalClients - returningClients
  const inactiveClients = Array.from(clientLastVisit.entries())
    .filter(([, last]) => last < ninetyDaysAgo).length

  const ltvValues = Array.from(clientSpend.values()).sort((a, b) => a - b)
  const avgLtv = ltvValues.length > 0
    ? Math.round(ltvValues.reduce((s, v) => s + v, 0) / ltvValues.length)
    : 0

  return {
    totalClients,
    newClients,
    returningClients,
    inactiveClients,
    avgLtv,
    retentionRate: totalClients > 0 ? Math.round((returningClients / totalClients) * 100) : 0,
  }
}

