import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface AiKpis {
  total: number
  totalCost: number
  totalTokens: number
  avgRating: number | null
}

interface ModelStat {
  model: string
  count: number
  cost: number
}

interface MonthlyPoint {
  month: string
  count: number
  cost: number
}

interface AiUsageBlock {
  kpis: AiKpis
  modelBreakdown: ModelStat[]
  monthlyTrend: MonthlyPoint[]
}

async function fetchAiData(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string | undefined,
  to: string | undefined,
): Promise<AiUsageBlock> {
  let outputQuery = supabase
    .from('ai_design_outputs')
    .select('id, model, tokens_input, tokens_output, cost_cents, rating, created_at')
    .eq('studio_id', studioId)

  if (from) outputQuery = outputQuery.gte('created_at', from)
  if (to) outputQuery = outputQuery.lte('created_at', to)

  const { data: outputs, error } = await outputQuery
  if (error) throw error

  const total = outputs?.length ?? 0
  const totalCost = (outputs ?? []).reduce((s, o) => s + (o.cost_cents ?? 0), 0)
  const totalTokens = (outputs ?? []).reduce((s, o) => s + (o.tokens_input ?? 0) + (o.tokens_output ?? 0), 0)
  const ratings = (outputs ?? []).filter((o) => o.rating != null).map((o) => o.rating as number)
  const avgRating = ratings.length > 0 ? ratings.reduce((s, r) => s + r, 0) / ratings.length : null

  const modelBreakdownMap = (outputs ?? []).reduce<Record<string, { count: number; cost: number }>>((acc, o) => {
    const model = o.model ?? 'unknown'
    if (!acc[model]) acc[model] = { count: 0, cost: 0 }
    acc[model].count++
    acc[model].cost += o.cost_cents ?? 0
    return acc
  }, {})

  const monthly = (outputs ?? []).reduce<Record<string, { count: number; cost: number }>>((acc, o) => {
    const month = o.created_at.slice(0, 7)
    if (!acc[month]) acc[month] = { count: 0, cost: 0 }
    acc[month].count++
    acc[month].cost += o.cost_cents ?? 0
    return acc
  }, {})

  const monthlyTrend = Object.entries(monthly)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([month, d]) => ({ month, ...d }))

  return {
    kpis: { total, totalCost, totalTokens, avgRating },
    modelBreakdown: Object.entries(modelBreakdownMap).map(([model, d]) => ({ model, ...d })),
    monthlyTrend,
  }
}

