import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface InventoryKpis {
  totalItems: number
  lowStockCount: number
  totalCogsConsumed: number
  stockValueCents: number
}

interface CategoryStat {
  name: string
  count: number
  /** Total stock value in cents — always integer cents for consistent 2-decimal formatting. */
  totalValue: number
}

interface InventoryBlock {
  kpis: InventoryKpis
  categoryBreakdown: CategoryStat[]
}

async function fetchInventoryData(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string | undefined,
  to: string | undefined,
): Promise<InventoryBlock> {
  const [itemsResult, movementsResult] = await Promise.all([
    supabase
      .from('inventory_items')
      .select('id, name, category, current_stock, min_threshold, cost_per_unit_cents, supplier_id')
      .eq('studio_id', studioId),
    supabase
      .from('inventory_movements')
      .select('item_id, qty_delta, reason, created_at, inventory_items(name, cost_per_unit_cents)')
      .eq('studio_id', studioId)
      .lt('qty_delta', 0) // consumption only
      .order('created_at', { ascending: false })
      .then((r) => {
        if (r.data) {
          let filtered = r.data
          if (from) filtered = filtered.filter((m) => m.created_at >= from)
          if (to) filtered = filtered.filter((m) => m.created_at <= to)
          return { ...r, data: filtered }
        }
        return r
      }),
  ])

  if (itemsResult.error) throw itemsResult.error
  if (movementsResult.error) throw movementsResult.error

  const items = itemsResult.data ?? []
  const movements = movementsResult.data ?? []

  // Definition: at or below threshold, and min_threshold is actually set (> 0).
  // Must match /api/inventory/stock-alerts directLowStockCount to keep UI counts consistent.
  const lowStockCount = items.filter(
    (i) => i.min_threshold > 0 && i.current_stock <= i.min_threshold,
  ).length

  const totalCogsConsumed = movements.reduce((sum, m) => {
    const item = m.inventory_items
    const cost = Array.isArray(item)
      ? (item[0]?.cost_per_unit_cents ?? 0)
      : ((item as { cost_per_unit_cents?: number } | null)?.cost_per_unit_cents ?? 0)
    return sum + Math.abs(m.qty_delta) * cost
  }, 0)

  // Stock value = quantity × cost per unit, stored in cents (integer) for consistent 2-decimal formatting
  const stockValueCents = items.reduce((sum, i) => {
    return sum + i.current_stock * i.cost_per_unit_cents
  }, 0)

  // Category breakdown — totalValue in cents (integer)
  const categoryMap = items.reduce<Record<string, { count: number; totalValue: number }>>((acc, i) => {
    const cat = i.category ?? 'Uncategorized'
    if (!acc[cat]) acc[cat] = { count: 0, totalValue: 0 }
    acc[cat].count++
    acc[cat].totalValue += Math.round(i.current_stock * i.cost_per_unit_cents)
    return acc
  }, {})

  return {
    kpis: { totalItems: items.length, lowStockCount, totalCogsConsumed, stockValueCents },
    categoryBreakdown: Object.entries(categoryMap).map(([name, d]) => ({ name, ...d })),
  }
}

