'use client'

import {
  Area,
  AreaChart,
  CartesianGrid,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts'
import { useChartTheme, type ChartTheme } from '@/lib/charts/theme'

interface DataPoint {
  name: string
  value: number
  [key: string]: string | number
}

interface PriorPoint {
  name: string
  value: number
}

interface RechartsAreaChartProps {
  data: DataPoint[]
  dataKey?: string
  label?: string
  formatValue?: (v: number) => string
  color?: string
  /** Optional chart theme override — uses useChartTheme() internally when absent */
  theme?: ChartTheme
  /** Prior-period series — renders as dashed Stone line when compare is active */
  priorData?: PriorPoint[]
  /** Label shown in tooltip for prior series, e.g. "Prior Last month ($18,400)" */
  priorLabel?: string
}

export default function RechartsAreaChart({
  data,
  dataKey = 'value',
  label = 'Value',
  formatValue,
  color,
  theme,
  priorData,
  priorLabel = 'Prior period',
}: RechartsAreaChartProps) {
  const hookTheme = useChartTheme()
  const ct = theme ?? hookTheme
  const seriesColor = color ?? ct.series[0]

  // Merge prior data into the chart data by aligning indices
  // Prior values are keyed as "prior" in each data point
  const mergedData: Array<{ name: string; value: number; prior?: number }> = data.map((d, i) => ({
    ...d,
    ...(priorData && priorData[i] !== undefined ? { prior: priorData[i]!.value } : {}),
  }))

  const hasPrior = Boolean(priorData && priorData.length > 0)

  // Stone color from brand tokens — safe to use as CSS var string in Recharts stroke
  const stoneColor = 'var(--color-stone)'

  return (
    <ResponsiveContainer width="100%" height={200}>
      <AreaChart data={mergedData} margin={{ top: 4, right: 4, bottom: 0, left: -20 }}>
        <defs>
          <linearGradient id="colorGradArea" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor={seriesColor} stopOpacity={0.18} />
            <stop offset="95%" stopColor={seriesColor} stopOpacity={0} />
          </linearGradient>
        </defs>
        <CartesianGrid strokeDasharray="3 3" stroke={ct.grid} vertical={false} />
        <XAxis
          dataKey="name"
          tick={{ fontSize: 11, fill: ct.text }}
          tickLine={false}
          axisLine={{ stroke: ct.axis }}
          interval="preserveStartEnd"
        />
        <YAxis
          tick={{ fontSize: 11, fill: ct.text }}
          tickLine={false}
          axisLine={{ stroke: ct.axis }}
          {...(formatValue ? { tickFormatter: formatValue } : {})}
        />
        <Tooltip
          contentStyle={{
            backgroundColor: ct.tooltip.background,
            borderColor: ct.tooltip.border,
            borderRadius: 'var(--radius-md)',
            fontSize: 12,
            boxShadow: 'var(--shadow-lift)',
          }}
          formatter={(v, name) => {
            const num = typeof v === 'number' ? v : 0
            if (name === 'prior') {
              return [formatValue ? formatValue(num) : num, priorLabel] as [string | number, string]
            }
            return [formatValue ? formatValue(num) : num, label] as [string | number, string]
          }}
          labelStyle={{ color: ct.tooltip.secondaryText, marginBottom: 4 }}
          itemStyle={{ color: ct.tooltip.text }}
        />
        <Area
          type="monotone"
          dataKey={dataKey}
          stroke={seriesColor}
          strokeWidth={2}
          fill="url(#colorGradArea)"
          dot={false}
          activeDot={{ r: 4, strokeWidth: 0, fill: seriesColor }}
        />
        {hasPrior && (
          <Line
            type="monotone"
            dataKey="prior"
            stroke={stoneColor}
            strokeWidth={1.5}
            strokeDasharray="4 4"
            dot={false}
            activeDot={{ r: 3, strokeWidth: 0, fill: stoneColor }}
          />
        )}
      </AreaChart>
    </ResponsiveContainer>
  )
}

