  const stoneColor = 'var(--color-stone)'

  // When prior data is present, use LineChart so we can overlay a dashed prior line over bars.
  // Recharts ComposedChart is the right tool here.
  if (hasPrior) {
    return (
      <ResponsiveContainer width="100%" height={200}>
        <BarChart data={mergedData} margin={{ top: 4, right: 4, bottom: 0, left: -20 }}>
          <CartesianGrid strokeDasharray="3 3" stroke={ct.grid} vertical={false} />
          <XAxis
            dataKey="name"
            tick={{ fontSize: 11, fill: ct.text }}
            tickLine={false}
            axisLine={{ stroke: ct.axis }}
          />
          <YAxis
            tick={{ fontSize: 11, fill: ct.text }}
            tickLine={false}
            axisLine={{ stroke: ct.axis }}
            {...(formatValue ? { tickFormatter: formatValue } : {})}
          />
          <Tooltip
            contentStyle={{
              backgroundColor: ct.tooltip.background,
              borderColor: ct.tooltip.border,
              borderRadius: 'var(--radius-md)',
              fontSize: 12,
              boxShadow: 'var(--shadow-lift)',
            }}
            formatter={(v, name) => {
              const num = typeof v === 'number' ? v : 0
              if (name === 'prior') {
                return [formatValue ? formatValue(num) : num, priorLabel] as [string | number, string]
              }
              return [formatValue ? formatValue(num) : num, label] as [string | number, string]
            }}
            labelStyle={{ color: ct.tooltip.secondaryText, marginBottom: 4 }}
            itemStyle={{ color: ct.tooltip.text }}
            cursor={{ fill: ct.grid, opacity: 0.6 }}
          />
          <Bar dataKey={dataKey} fill={seriesColor} radius={[3, 3, 0, 0]} />
          {/* Dashed prior line overlaid on bars — uses a hidden Line which Recharts renders on top */}
          <Line
            type="monotone"
            dataKey="prior"
            stroke={stoneColor}
            strokeWidth={1.5}
            strokeDasharray="4 4"
            dot={false}
            activeDot={{ r: 3, strokeWidth: 0, fill: stoneColor }}
          />
        </BarChart>
      </ResponsiveContainer>
    )
  }

  return (
    <ResponsiveContainer width="100%" height={200}>
      <BarChart data={mergedData} margin={{ top: 4, right: 4, bottom: 0, left: -20 }}>
        <CartesianGrid strokeDasharray="3 3" stroke={ct.grid} vertical={false} />
        <XAxis
          dataKey="name"
          tick={{ fontSize: 11, fill: ct.text }}
          tickLine={false}
          axisLine={{ stroke: ct.axis }}
        />
        <YAxis
          tick={{ fontSize: 11, fill: ct.text }}
          tickLine={false}
          axisLine={{ stroke: ct.axis }}
          {...(formatValue ? { tickFormatter: formatValue } : {})}
        />
        <Tooltip
          contentStyle={{
            backgroundColor: ct.tooltip.background,
            borderColor: ct.tooltip.border,
            borderRadius: 'var(--radius-md)',
            fontSize: 12,
            boxShadow: 'var(--shadow-lift)',
          }}
          formatter={(v) => {
            const num = typeof v === 'number' ? v : 0
            return [formatValue ? formatValue(num) : num, label] as [string | number, string]
          }}
          labelStyle={{ color: ct.tooltip.secondaryText, marginBottom: 4 }}
          itemStyle={{ color: ct.tooltip.text }}
          cursor={{ fill: ct.grid, opacity: 0.6 }}
        />
        <Bar dataKey={dataKey} fill={seriesColor} radius={[3, 3, 0, 0]} />
      </BarChart>
    </ResponsiveContainer>
  )
}

