'use client'

import { useState, useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { DollarSign, TrendingUp, BarChart2, LineChart as LineChartIcon } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { Skeleton } from '@/components/ui/skeleton'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'
import dynamic from 'next/dynamic'

const RechartsAreaChart = dynamic(() => import('./RechartsAreaChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})
const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

type GroupBy = 'day' | 'week' | 'month'
type ChartMode = 'line' | 'bar'

interface RevenueKpis {
  totalRevenue: number
  avgSessionValue: number
  depositsCollected: number
  tipsCollected: number
  sessionsCompleted: number
}

interface RevenueTimeline {
  period: string
  revenue: number
  deposits: number
  tips: number
  count: number
}

interface RevenueBlock {
  timeline: RevenueTimeline[]
  kpis: RevenueKpis
}

interface RevenueResponse {
  current: RevenueBlock
  prior?: RevenueBlock
}

export function RevenueReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const [groupBy, setGroupBy] = useState<GroupBy>('day')
  const [chartMode, setChartMode] = useState<ChartMode>('line')

  const { data, isLoading, error } = useQuery<RevenueResponse>({
    queryKey: ['reports', 'revenue', groupBy, from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams({ group_by: groupBy })
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/revenue?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.timeline ?? []).map((r) => ({
      period: r.period,
      revenue: formatCurrency(r.revenue),
      deposits: formatCurrency(r.deposits),
      tips: formatCurrency(r.tips),
      sessions: r.count,
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-revenue',
    getRows,
    headers: { period: 'Period', revenue: 'Revenue', deposits: 'Deposits', tips: 'Tips', sessions: 'Sessions' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      emptySlot={
        <EmptyState
          icon={TrendingUp}
          title="No revenue data yet"
          description="Revenue will populate once your first payment is processed."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis

        // Timeline for chart
        const timelineForChart = d.timeline.map((r) => ({
          name: r.period,
          // Revenue chart shows dollars (divide cents by 100)
          value: Math.round(r.revenue / 100),
        }))

        // Prior timeline aligned by index (periods may not match labels when ranges differ)
        const priorTimelineForChart = prior?.timeline.map((r) => ({
          name: r.period,
          value: Math.round(r.revenue / 100),
        }))

        // Compare deltas
        const revenueDeltaRaw = computeDelta(kpis.totalRevenue, priorKpis?.totalRevenue)
        const sessionsDeltaRaw = computeDelta(kpis.sessionsCompleted, priorKpis?.sessionsCompleted)
        const avgSessionDeltaRaw = computeDelta(kpis.avgSessionValue, priorKpis?.avgSessionValue)
        const depositsDeltaRaw = computeDelta(kpis.depositsCollected, priorKpis?.depositsCollected)

        const showDeltas = compare === '1' && priorKpis !== undefined
        const priorLabel = prior ? `Prior period` : undefined

        const revenueDelta = showDeltas ? formatPercent(revenueDeltaRaw) : undefined
        const sessionsDelta = showDeltas ? formatPercent(sessionsDeltaRaw) : undefined
        const avgSessionDelta = showDeltas ? formatPercent(avgSessionDeltaRaw) : undefined
        const depositsDelta = showDeltas ? formatPercent(depositsDeltaRaw) : undefined

        const revenueTrend = revenueDeltaRaw !== null && revenueDeltaRaw > 0 ? 'up' : revenueDeltaRaw !== null && revenueDeltaRaw < 0 ? 'down' : 'neutral'
        const sessionsTrend = sessionsDeltaRaw !== null && sessionsDeltaRaw > 0 ? 'up' : sessionsDeltaRaw !== null && sessionsDeltaRaw < 0 ? 'down' : 'neutral'
        const avgSessionTrend = avgSessionDeltaRaw !== null && avgSessionDeltaRaw > 0 ? 'up' : avgSessionDeltaRaw !== null && avgSessionDeltaRaw < 0 ? 'down' : 'neutral'
        const depositsTrend = depositsDeltaRaw !== null && depositsDeltaRaw > 0 ? 'up' : depositsDeltaRaw !== null && depositsDeltaRaw < 0 ? 'down' : 'neutral'

        // Tips as subtextLabel on Revenue KPI card
        const tipsLabel = kpis.tipsCollected > 0
          ? `${formatCurrency(kpis.tipsCollected)} in tips included`
          : 'all sessions'

        const priorPeriodLabel = showDeltas ? 'vs prior period' : undefined

        // Chart tooltip: when value = 0, show "Closed" instead of "$0"
        // (v1: any $0 day is labelled Closed; future: check studio operating hours config)
        const revenueFormatValue = (v: number) => v === 0 ? 'Closed' : `$${v.toLocaleString()}`

        return (
          <div className="space-y-6">
            {/* Period + chart mode controls */}
            <div className="flex flex-wrap items-center gap-3">
              <ToggleGroup
                value={[groupBy]}
                onValueChange={(values) => {
                  const v = values[values.length - 1]
                  if (v) setGroupBy(v as GroupBy)
                }}
                className="border border-border rounded-md p-0.5"
              >
                <ToggleGroupItem value="day" size="sm">Daily</ToggleGroupItem>
                <ToggleGroupItem value="week" size="sm">Weekly</ToggleGroupItem>
                <ToggleGroupItem value="month" size="sm">Monthly</ToggleGroupItem>
              </ToggleGroup>

              {/* Line / Bar mode toggle */}
              <div className="flex items-center gap-1 border border-border rounded-md p-0.5">
                <Button
                  size="sm"
                  variant={chartMode === 'line' ? 'secondary' : 'ghost'}
                  className="h-7 px-2"
                  onClick={() => setChartMode('line')}
                  aria-pressed={chartMode === 'line'}
                  aria-label="Line chart"
                >
                  <LineChartIcon className="h-3.5 w-3.5 mr-1" aria-hidden="true" />
                  Line
                </Button>
                <Button
                  size="sm"
                  variant={chartMode === 'bar' ? 'secondary' : 'ghost'}
                  className="h-7 px-2"
                  onClick={() => setChartMode('bar')}
                  aria-pressed={chartMode === 'bar'}
                  aria-label="Bar chart"
                >
                  <BarChart2 className="h-3.5 w-3.5 mr-1" aria-hidden="true" />
                  Bar
                </Button>
              </div>
            </div>

            {/* 4 KPI cards (Tips folded into Revenue card) */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Revenue"
                value={formatCurrency(kpis.totalRevenue)}
                subtextLabel={revenueDelta ? priorPeriodLabel : tipsLabel}
                icon={DollarSign}
                delta={revenueDelta ?? undefined}
                trend={revenueTrend}
                index={0}
              />
              <KpiCard
                label="Sessions"
                value={kpis.sessionsCompleted}
                subtextLabel={sessionsDelta ? priorPeriodLabel : 'completed'}
                icon={TrendingUp}
                delta={sessionsDelta ?? undefined}
                trend={sessionsTrend}
                index={1}
              />
              <KpiCard
                label="Avg Session"
                value={formatCurrency(kpis.avgSessionValue)}
                subtextLabel={avgSessionDelta ? priorPeriodLabel : 'per completed booking'}
                icon={TrendingUp}
                delta={avgSessionDelta ?? undefined}
                trend={avgSessionTrend}
                index={2}
              />
              <KpiCard
                label="Deposits Collected"
                value={formatCurrency(kpis.depositsCollected)}
                subtextLabel={depositsDelta ? priorPeriodLabel : 'collected'}
                icon={DollarSign}
                delta={depositsDelta ?? undefined}
                trend={depositsTrend}
                index={3}
              />
            </div>

            {/* Single Revenue-over-Time chart with line/bar mode toggle */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Revenue Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                {timelineForChart.length === 0 ? (
                  <EmptyState icon={DollarSign} title="No revenue data yet" description="Completed sessions will appear here." />
                ) : chartMode === 'line' ? (
                  <RechartsAreaChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Revenue"
                    formatValue={revenueFormatValue}
                    priorData={priorTimelineForChart}
                    priorLabel={priorLabel}
                  />
                ) : (
                  <RechartsBarChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Revenue"
                    formatValue={revenueFormatValue}
                    priorData={priorTimelineForChart}
                    priorLabel={priorLabel}
                  />
                )}
              </CardContent>
            </Card>
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users, UserPlus, Repeat, DollarSign } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'

interface ClientsKpis {
  totalClients: number
  newClients: number
  returningClients: number
  inactiveClients: number
  avgLtv: number
  retentionRate: number
}

interface ClientsResponse {
  current: ClientsKpis
  prior?: ClientsKpis
}

export function ClientsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<ClientsResponse>({
    queryKey: ['reports', 'clients', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/clients?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    if (!data?.current) return []
    const d = data.current
    return [
      { metric: 'Total Clients', value: d.totalClients },
      { metric: 'New Clients', value: d.newClients },
      { metric: 'Retention Rate', value: `${d.retentionRate}%` },
      { metric: 'Avg LTV', value: formatCurrency(d.avgLtv) },
    ]
  }, [data])

  useExportCsv({
    filename: 'analytics-clients',
    getRows,
    headers: { metric: 'Metric', value: 'Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={5} />}
      emptySlot={
        <EmptyState
          icon={Users}
          title="No client data yet"
          description="Client retention metrics will appear after their first visit."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const showDeltas = compare === '1' && prior !== undefined

        // Deltas
        const totalDeltaRaw = computeDelta(d.totalClients, prior?.totalClients)
        const newDeltaRaw = computeDelta(d.newClients, prior?.newClients)
        const retentionDeltaRaw = computeDelta(d.retentionRate, prior?.retentionRate)
        const ltvDeltaRaw = computeDelta(d.avgLtv, prior?.avgLtv)

        const totalDelta = showDeltas ? (formatPercent(totalDeltaRaw) ?? undefined) : undefined
        const newDelta = showDeltas ? (formatPercent(newDeltaRaw) ?? undefined) : undefined
        const retentionDelta = showDeltas ? (formatPercent(retentionDeltaRaw) ?? undefined) : undefined
        const ltvDelta = showDeltas ? (formatPercent(ltvDeltaRaw) ?? undefined) : undefined

        const totalTrend = totalDeltaRaw !== null && totalDeltaRaw > 0 ? 'up' : totalDeltaRaw !== null && totalDeltaRaw < 0 ? 'down' : 'neutral'
        const newTrend = newDeltaRaw !== null && newDeltaRaw > 0 ? 'up' : newDeltaRaw !== null && newDeltaRaw < 0 ? 'down' : 'neutral'
        // Retention: higher = better
        const retentionTrend = retentionDeltaRaw !== null && retentionDeltaRaw > 0 ? 'up' : retentionDeltaRaw !== null && retentionDeltaRaw < 0 ? 'down' : 'neutral'
        const ltvTrend = ltvDeltaRaw !== null && ltvDeltaRaw > 0 ? 'up' : ltvDeltaRaw !== null && ltvDeltaRaw < 0 ? 'down' : 'neutral'

        const priorLabel = showDeltas ? 'vs prior period' : undefined

        return (
          <div className="space-y-6">
            {/* 4 KPI cards — varied lucide icons per metric, no identical person-icons */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Clients"
                value={d.totalClients}
                subtextLabel={totalDelta ? priorLabel : 'all time'}
                icon={Users}
                delta={totalDelta}
                trend={totalTrend}
                index={0}
              />
              <KpiCard
                label="New This Period"
                value={d.newClients}
                subtextLabel={newDelta ? priorLabel : 'first booking only'}
                icon={UserPlus}
                delta={newDelta}
                trend={newTrend}
                index={1}
              />
              <KpiCard
                label="Retention Rate"
                value={`${d.retentionRate}%`}
                subtextLabel={retentionDelta ? priorLabel : 'return after first visit'}
                icon={Repeat}
                delta={retentionDelta}
                trend={retentionTrend}
                index={2}
              />
              <KpiCard
                label="Avg LTV"
                value={formatCurrency(d.avgLtv)}
                subtextLabel={ltvDelta ? priorLabel : 'lifetime value per client'}
                icon={DollarSign}
                delta={ltvDelta}
                trend={ltvTrend}
                index={3}
              />
            </div>
          </div>
        )
      }}
    </DataState>
  )
}

