import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface ModelStat {
  model: string
  count: number
  cost: number
}

interface MonthlyPoint {
  month: string
  count: number
  cost: number
}

interface AiKpis {
  total: number
  totalCost: number
  totalTokens: number
  avgRating: number | null
}

interface AiUsageBlock {
  kpis: AiKpis
  modelBreakdown: ModelStat[]
  monthlyTrend: MonthlyPoint[]
}

interface AiUsageResponse {
  current: AiUsageBlock
  prior?: AiUsageBlock
}

export function AiUsageReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<AiUsageResponse>({
    queryKey: ['reports', 'ai', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/ai?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.monthlyTrend ?? []).map((p) => ({
      month: p.month,
      generations: p.count,
      cost: formatCurrency(p.cost),
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-ai',
    getRows,
    headers: { month: 'Month', generations: 'Generations', cost: 'Cost' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      isEmpty={data?.current.kpis.total === 0}
      emptySlot={
        <EmptyState
          icon={Wand2}
          title="No AI generations yet"
          description="AI design generations will appear here once clients start using the feature."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const showDeltas = compare === '1' && prior !== undefined

        const kpis = d.kpis
        const priorKpis = prior?.kpis

        // Deltas
        const totalDeltaRaw = computeDelta(kpis.total, priorKpis?.total)
        const costDeltaRaw = computeDelta(kpis.totalCost, priorKpis?.totalCost)
        const tokensDeltaRaw = computeDelta(kpis.totalTokens, priorKpis?.totalTokens)
        const ratingDeltaRaw =
          kpis.avgRating !== null && priorKpis?.avgRating !== null && priorKpis?.avgRating !== undefined
            ? computeDelta(kpis.avgRating, priorKpis.avgRating)
            : null

        const totalDelta = showDeltas ? (formatPercent(totalDeltaRaw) ?? undefined) : undefined
        const costDelta = showDeltas ? (formatPercent(costDeltaRaw) ?? undefined) : undefined
        const tokensDelta = showDeltas ? (formatPercent(tokensDeltaRaw) ?? undefined) : undefined
        const ratingDelta = showDeltas ? (formatPercent(ratingDeltaRaw) ?? undefined) : undefined

        const totalTrend = totalDeltaRaw !== null && totalDeltaRaw > 0 ? 'up' : totalDeltaRaw !== null && totalDeltaRaw < 0 ? 'down' : 'neutral'
        const costTrend = costDeltaRaw !== null && costDeltaRaw > 0 ? 'up' : costDeltaRaw !== null && costDeltaRaw < 0 ? 'down' : 'neutral'
        const tokensTrend = tokensDeltaRaw !== null && tokensDeltaRaw > 0 ? 'up' : tokensDeltaRaw !== null && tokensDeltaRaw < 0 ? 'down' : 'neutral'
        const ratingTrend = ratingDeltaRaw !== null && ratingDeltaRaw > 0 ? 'up' : ratingDeltaRaw !== null && ratingDeltaRaw < 0 ? 'down' : 'neutral'

        const priorLabel = showDeltas ? 'vs prior period' : undefined

        const trendForChart = d.monthlyTrend.map((p) => ({
          name: p.month,
          value: Math.round(p.cost / 100),
        }))

        const priorTrendForChart = prior?.monthlyTrend.map((p) => ({
          name: p.month,
          value: Math.round(p.cost / 100),
        }))

        // Monthly cost chart empty state: show only when 2+ data points exist
        const hasEnoughTrendData = trendForChart.length >= 2

        return (
          <div className="space-y-6">
            {/* KPIs */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Generations"
                value={kpis.total}
                subtextLabel={totalDelta ? priorLabel : 'total AI calls'}
                icon={Wand2}
                delta={totalDelta}
                trend={totalTrend}
                index={0}
              />
              <KpiCard
                label="Total Cost"
                value={formatCurrency(kpis.totalCost)}
                subtextLabel={costDelta ? priorLabel : 'charged to studio'}
                icon={DollarSign}
                delta={costDelta}
                trend={costTrend}
                index={1}
              />
              <KpiCard
                label="Tokens Used"
                value={kpis.totalTokens.toLocaleString()}
                subtextLabel={tokensDelta ? priorLabel : 'input + output'}
                icon={Wand2}
                delta={tokensDelta}
                trend={tokensTrend}
                index={2}
              />
              <KpiCard
                label="Avg Rating"
                value={kpis.avgRating != null ? `${kpis.avgRating.toFixed(1)} / 5` : 'No ratings'}
                subtextLabel={ratingDelta ? priorLabel : 'user satisfaction'}
                icon={Star}
                delta={ratingDelta}
                trend={ratingTrend}
                index={3}
              />
            </div>

            {/* Monthly cost trend — empty state when < 2 data points */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Monthly AI Cost ($)</CardTitle>
              </CardHeader>
              <CardContent>
                {hasEnoughTrendData ? (
                  <RechartsBarChart
                    data={trendForChart}
                    dataKey="value"
                    label="Cost ($)"
                    formatValue={(v) => `$${v}`}
                    priorData={priorTrendForChart}
                    priorLabel={priorLabel}
                  />
                ) : (
                  <EmptyState
                    icon={Wand2}
                    variant="coming-soon"
                    title="Awaiting more data"
                    description="Add another month of usage to see the trend."
                  />
                )}
              </CardContent>
            </Card>

            {/* Model breakdown */}
            {d.modelBreakdown.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Model Breakdown</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.modelBreakdown
                      .sort((a, b) => b.cost - a.cost)
                      .map((m) => (
                        <div key={m.model} className="flex items-center gap-4 px-6 py-4">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium font-mono truncate">{m.model}</p>
                            <p className="text-xs text-muted-foreground">{m.count} generations</p>
                          </div>
                          <div className="text-right shrink-0">
                            <p className="text-sm font-semibold tabular-nums">{formatCurrency(m.cost)}</p>
                            <p className="text-xs text-muted-foreground">total cost</p>
                          </div>
                          <Badge variant="secondary" className="shrink-0 font-mono">
                            {Math.round(m.cost / Math.max(m.count, 1))}¢ avg
                          </Badge>
                        </div>
                      ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

