import { useExportCsv } from '@/hooks/use-export-csv'

interface CategoryStat {
  name: string
  count: number
  /** Total stock value in cents */
  totalValue: number
}

interface InventoryKpis {
  totalItems: number
  lowStockCount: number
  totalCogsConsumed: number
  stockValueCents: number
}

interface InventoryBlock {
  kpis: InventoryKpis
  categoryBreakdown: CategoryStat[]
}

interface InventoryResponse {
  current: InventoryBlock
  prior?: InventoryBlock
}

export function InventoryReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<InventoryResponse>({
    queryKey: ['reports', 'inventory', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/inventory?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.categoryBreakdown ?? []).map((c) => ({
      category: c.name,
      items: c.count,
      stockValue: formatCurrency(c.totalValue),
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-inventory',
    getRows,
    headers: { category: 'Category', items: 'Items', stockValue: 'Stock Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={3} />}
      emptySlot={
        <EmptyState
          icon={Package}
          title="No inventory data yet"
          description="Add inventory items to start tracking COGS and category breakdown."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis
        const showDeltas = compare === '1' && priorKpis !== undefined

        // Low stock and COGS are inverse metrics: higher = bad → invertTrend
        const lowStockDeltaRaw = computeDelta(kpis.lowStockCount, priorKpis?.lowStockCount)
        const cogsDeltaRaw = computeDelta(kpis.totalCogsConsumed, priorKpis?.totalCogsConsumed)
        const stockValueDeltaRaw = computeDelta(kpis.stockValueCents, priorKpis?.stockValueCents)

        const lowStockDelta = showDeltas ? (formatPercent(lowStockDeltaRaw) ?? undefined) : undefined
        const cogsDelta = showDeltas ? (formatPercent(cogsDeltaRaw) ?? undefined) : undefined
        const stockValueDelta = showDeltas ? (formatPercent(stockValueDeltaRaw) ?? undefined) : undefined

        // Low stock: higher count = bad → invertTrend
        const lowStockTrend = lowStockDeltaRaw !== null && lowStockDeltaRaw > 0 ? 'up' : lowStockDeltaRaw !== null && lowStockDeltaRaw < 0 ? 'down' : 'neutral'
        const cogsRawTrend = cogsDeltaRaw !== null && cogsDeltaRaw > 0 ? 'up' : cogsDeltaRaw !== null && cogsDeltaRaw < 0 ? 'down' : 'neutral'
        const stockValueTrend = stockValueDeltaRaw !== null && stockValueDeltaRaw > 0 ? 'up' : stockValueDeltaRaw !== null && stockValueDeltaRaw < 0 ? 'down' : 'neutral'

        const priorLabel = showDeltas ? 'vs prior period' : undefined

        return (
          <div className="space-y-6">
            {/* 4 KPI cards */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Items"
                value={kpis.totalItems}
                subtextLabel="in inventory"
                icon={Package}
                index={0}
              />
              <KpiCard
                label="Low Stock"
                value={kpis.lowStockCount}
                subtextLabel={lowStockDelta ? priorLabel : 'items below threshold'}
                icon={AlertTriangle}
                invertTrend
                trend={kpis.lowStockCount > 0 ? lowStockTrend : 'neutral'}
                delta={lowStockDelta}
                index={1}
              />
              <KpiCard
                label="COGS Consumed"
                value={formatCurrency(kpis.totalCogsConsumed)}
                subtextLabel={cogsDelta ? priorLabel : 'cost of goods used'}
                icon={DollarSign}
                delta={cogsDelta}
                trend={cogsRawTrend}
                index={2}
              />
              <KpiCard
                label="Stock Value"
                value={formatCurrency(kpis.stockValueCents)}
                subtextLabel={stockValueDelta ? priorLabel : 'current inventory value'}
                icon={BarChart2}
                delta={stockValueDelta}
                trend={stockValueTrend}
                index={3}
              />
            </div>

            {/* Category breakdown — totalValue always formatted via formatCurrency (cents) */}
            {d.categoryBreakdown.length === 0 ? (
              <EmptyState
                icon={Package}
                title="No category data"
                description="Add inventory items to see category breakdown."
              />
            ) : (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Inventory by Category</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.categoryBreakdown
                      .sort((a, b) => b.totalValue - a.totalValue)
                      .map((cat) => (
                        <div key={cat.name} className="flex items-center gap-4 px-6 py-4">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium truncate">{cat.name}</p>
                            <p className="text-xs text-muted-foreground">{cat.count} items</p>
                          </div>
                          <div className="text-right shrink-0">
                            {/* formatCurrency(cents) always produces 2-decimal output — no raw toFixed() */}
                            <p className="text-sm font-semibold tabular-nums">{formatCurrency(cat.totalValue)}</p>
                            <p className="text-xs text-muted-foreground">stock value</p>
                          </div>
                          <Badge variant={cat.count < 3 ? 'destructive' : 'secondary'} className="shrink-0">
                            {cat.count}
                          </Badge>
                        </div>
                      ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

