'use client'

import { useState, useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { DollarSign, TrendingUp, BarChart2, LineChart as LineChartIcon } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { Skeleton } from '@/components/ui/skeleton'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'
import dynamic from 'next/dynamic'

const RechartsAreaChart = dynamic(() => import('./RechartsAreaChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})
const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

type GroupBy = 'day' | 'week' | 'month'
type ChartMode = 'line' | 'bar'

interface RevenueKpis {
  totalRevenue: number
  avgSessionValue: number
  depositsCollected: number
  tipsCollected: number
  sessionsCompleted: number
}

interface RevenueTimeline {
  period: string
  revenue: number
  deposits: number
  tips: number
  count: number
}

interface RevenueBlock {
  timeline: RevenueTimeline[]
  kpis: RevenueKpis
}

interface RevenueResponse {
  current: RevenueBlock
  prior?: RevenueBlock
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function RevenueReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const [groupBy, setGroupBy] = useState<GroupBy>('day')
  const [chartMode, setChartMode] = useState<ChartMode>('line')

  const { data, isLoading, error } = useQuery<RevenueResponse>({
    queryKey: ['reports', 'revenue', groupBy, from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams({ group_by: groupBy })
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/revenue?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.timeline ?? []).map((r) => ({
      period: r.period,
      revenue: formatCurrency(r.revenue),
      deposits: formatCurrency(r.deposits),
      tips: formatCurrency(r.tips),
      sessions: r.count,
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-revenue',
    getRows,
    headers: { period: 'Period', revenue: 'Revenue', deposits: 'Deposits', tips: 'Tips', sessions: 'Sessions' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      emptySlot={
        <EmptyState
          icon={TrendingUp}
          title="No revenue data yet"
          description="Revenue will populate once your first payment is processed."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis

        const timelineForChart = d.timeline.map((r) => ({
          name: r.period,
          value: Math.round(r.revenue / 100),
        }))

        const priorTimelineForChart = prior?.timeline.map((r) => ({
          name: r.period,
          value: Math.round(r.revenue / 100),
        }))

        const showDeltas = compare === '1' && priorKpis !== undefined

        const revenueDeltaRaw = computeDelta(kpis.totalRevenue, priorKpis?.totalRevenue)
        const sessionsDeltaRaw = computeDelta(kpis.sessionsCompleted, priorKpis?.sessionsCompleted)
        const avgSessionDeltaRaw = computeDelta(kpis.avgSessionValue, priorKpis?.avgSessionValue)
        const depositsDeltaRaw = computeDelta(kpis.depositsCollected, priorKpis?.depositsCollected)

        const revenueDelta = showDeltas ? formatPercent(revenueDeltaRaw) : null
        const sessionsDelta = showDeltas ? formatPercent(sessionsDeltaRaw) : null
        const avgSessionDelta = showDeltas ? formatPercent(avgSessionDeltaRaw) : null
        const depositsDelta = showDeltas ? formatPercent(depositsDeltaRaw) : null

        const priorPeriodLabel = 'vs prior period'

        // Tips as subtextLabel on Revenue KPI — only show when no delta
        const tipsLabel = kpis.tipsCollected > 0
          ? `${formatCurrency(kpis.tipsCollected)} in tips included`
          : 'all sessions'

        // Chart tooltip: when value = 0, show "Closed" instead of "$0"
        // v1: any $0 day is labelled Closed — future: check studio operating hours config
        const revenueFormatValue = (v: number) => v === 0 ? 'Closed' : `$${v.toLocaleString()}`

        const priorLabel = 'Prior period'

        return (
          <div className="space-y-6">
            {/* Period + chart mode controls */}
            <div className="flex flex-wrap items-center gap-3">
              <ToggleGroup
                value={[groupBy]}
                onValueChange={(values) => {
                  const v = values[values.length - 1]
                  if (v) setGroupBy(v as GroupBy)
                }}
                className="border border-border rounded-md p-0.5"
              >
                <ToggleGroupItem value="day" size="sm">Daily</ToggleGroupItem>
                <ToggleGroupItem value="week" size="sm">Weekly</ToggleGroupItem>
                <ToggleGroupItem value="month" size="sm">Monthly</ToggleGroupItem>
              </ToggleGroup>

              {/* Line / Bar mode toggle */}
              <div className="flex items-center gap-1 border border-border rounded-md p-0.5">
                <Button
                  size="sm"
                  variant={chartMode === 'line' ? 'secondary' : 'ghost'}
                  className="h-7 px-2"
                  onClick={() => setChartMode('line')}
                  aria-pressed={chartMode === 'line'}
                  aria-label="Line chart"
                >
                  <LineChartIcon className="h-3.5 w-3.5 mr-1" aria-hidden="true" />
                  Line
                </Button>
                <Button
                  size="sm"
                  variant={chartMode === 'bar' ? 'secondary' : 'ghost'}
                  className="h-7 px-2"
                  onClick={() => setChartMode('bar')}
                  aria-pressed={chartMode === 'bar'}
                  aria-label="Bar chart"
                >
                  <BarChart2 className="h-3.5 w-3.5 mr-1" aria-hidden="true" />
                  Bar
                </Button>
              </div>
            </div>

            {/* 4 KPI cards — Tips folded into Revenue card as subtextLabel */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Revenue"
                value={formatCurrency(kpis.totalRevenue)}
                subtextLabel={revenueDelta ? priorPeriodLabel : tipsLabel}
                icon={DollarSign}
                trend={trendOf(revenueDeltaRaw)}
                index={0}
                {...(revenueDelta !== null ? { delta: revenueDelta } : {})}
              />
              <KpiCard
                label="Sessions"
                value={kpis.sessionsCompleted}
                subtextLabel={sessionsDelta ? priorPeriodLabel : 'completed'}
                icon={TrendingUp}
                trend={trendOf(sessionsDeltaRaw)}
                index={1}
                {...(sessionsDelta !== null ? { delta: sessionsDelta } : {})}
              />
              <KpiCard
                label="Avg Session"
                value={formatCurrency(kpis.avgSessionValue)}
                subtextLabel={avgSessionDelta ? priorPeriodLabel : 'per completed booking'}
                icon={TrendingUp}
                trend={trendOf(avgSessionDeltaRaw)}
                index={2}
                {...(avgSessionDelta !== null ? { delta: avgSessionDelta } : {})}
              />
              <KpiCard
                label="Deposits Collected"
                value={formatCurrency(kpis.depositsCollected)}
                subtextLabel={depositsDelta ? priorPeriodLabel : 'collected'}
                icon={DollarSign}
                trend={trendOf(depositsDeltaRaw)}
                index={3}
                {...(depositsDelta !== null ? { delta: depositsDelta } : {})}
              />
            </div>

            {/* Single Revenue-over-Time chart with line/bar mode toggle */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Revenue Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                {timelineForChart.length === 0 ? (
                  <EmptyState icon={DollarSign} title="No revenue data yet" description="Completed sessions will appear here." />
                ) : chartMode === 'line' ? (
                  <RechartsAreaChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Revenue"
                    formatValue={revenueFormatValue}
                    {...(priorTimelineForChart ? { priorData: priorTimelineForChart, priorLabel } : {})}
                  />
                ) : (
                  <RechartsBarChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Revenue"
                    formatValue={revenueFormatValue}
                    {...(priorTimelineForChart ? { priorData: priorTimelineForChart, priorLabel } : {})}
                  />
                )}
              </CardContent>
            </Card>
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users, UserPlus, Repeat, DollarSign } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'

interface ClientsKpis {
  totalClients: number
  newClients: number
  returningClients: number
  inactiveClients: number
  avgLtv: number
  retentionRate: number
}

interface ClientsResponse {
  current: ClientsKpis
  prior?: ClientsKpis
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function ClientsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<ClientsResponse>({
    queryKey: ['reports', 'clients', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/clients?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    if (!data?.current) return []
    const d = data.current
    return [
      { metric: 'Total Clients', value: String(d.totalClients) },
      { metric: 'New Clients', value: String(d.newClients) },
      { metric: 'Retention Rate', value: `${d.retentionRate}%` },
      { metric: 'Avg LTV', value: formatCurrency(d.avgLtv) },
    ]
  }, [data])

  useExportCsv({
    filename: 'analytics-clients',
    getRows,
    headers: { metric: 'Metric', value: 'Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={5} />}
      emptySlot={
        <EmptyState
          icon={Users}
          title="No client data yet"
          description="Client retention metrics will appear after their first visit."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const showDeltas = compare === '1' && prior !== undefined

        const totalDeltaRaw = computeDelta(d.totalClients, prior?.totalClients)
        const newDeltaRaw = computeDelta(d.newClients, prior?.newClients)
        const retentionDeltaRaw = computeDelta(d.retentionRate, prior?.retentionRate)
        const ltvDeltaRaw = computeDelta(d.avgLtv, prior?.avgLtv)

        const totalDelta = showDeltas ? formatPercent(totalDeltaRaw) : null
        const newDelta = showDeltas ? formatPercent(newDeltaRaw) : null
        const retentionDelta = showDeltas ? formatPercent(retentionDeltaRaw) : null
        const ltvDelta = showDeltas ? formatPercent(ltvDeltaRaw) : null

        const priorLabel = 'vs prior period'

        return (
          <div className="space-y-6">
            {/* 4 KPI cards — varied lucide icons per metric, no identical person-icons */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Clients"
                value={d.totalClients}
                subtextLabel={totalDelta ? priorLabel : 'all time'}
                icon={Users}
                trend={trendOf(totalDeltaRaw)}
                index={0}
                {...(totalDelta !== null ? { delta: totalDelta } : {})}
              />
              <KpiCard
                label="New This Period"
                value={d.newClients}
                subtextLabel={newDelta ? priorLabel : 'first booking only'}
                icon={UserPlus}
                trend={trendOf(newDeltaRaw)}
                index={1}
                {...(newDelta !== null ? { delta: newDelta } : {})}
              />
              <KpiCard
                label="Retention Rate"
                value={`${d.retentionRate}%`}
                subtextLabel={retentionDelta ? priorLabel : 'return after first visit'}
                icon={Repeat}
                trend={trendOf(retentionDeltaRaw)}
                index={2}
                {...(retentionDelta !== null ? { delta: retentionDelta } : {})}
              />
              <KpiCard
                label="Avg LTV"
                value={formatCurrency(d.avgLtv)}
                subtextLabel={ltvDelta ? priorLabel : 'lifetime value per client'}
                icon={DollarSign}
                trend={trendOf(ltvDeltaRaw)}
                index={3}
                {...(ltvDelta !== null ? { delta: ltvDelta } : {})}
              />
            </div>
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Wand2, DollarSign, Star } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface ModelStat {
  model: string
  count: number
  cost: number
}

interface MonthlyPoint {
  month: string
  count: number
  cost: number
}

interface AiKpis {
  total: number
  totalCost: number
  totalTokens: number
  avgRating: number | null
}

interface AiUsageBlock {
  kpis: AiKpis
  modelBreakdown: ModelStat[]
  monthlyTrend: MonthlyPoint[]
}

interface AiUsageResponse {
  current: AiUsageBlock
  prior?: AiUsageBlock
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function AiUsageReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<AiUsageResponse>({
    queryKey: ['reports', 'ai', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/ai?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.monthlyTrend ?? []).map((p) => ({
      month: p.month,
      generations: String(p.count),
      cost: formatCurrency(p.cost),
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-ai',
    getRows,
    headers: { month: 'Month', generations: 'Generations', cost: 'Cost' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      isEmpty={data?.current.kpis.total === 0}
      emptySlot={
        <EmptyState
          icon={Wand2}
          title="No AI generations yet"
          description="AI design generations will appear here once clients start using the feature."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const showDeltas = compare === '1' && prior !== undefined

        const kpis = d.kpis
        const priorKpis = prior?.kpis

        const totalDeltaRaw = computeDelta(kpis.total, priorKpis?.total)
        const costDeltaRaw = computeDelta(kpis.totalCost, priorKpis?.totalCost)
        const tokensDeltaRaw = computeDelta(kpis.totalTokens, priorKpis?.totalTokens)
        const ratingDeltaRaw =
          kpis.avgRating !== null && priorKpis?.avgRating != null
            ? computeDelta(kpis.avgRating, priorKpis.avgRating)
            : null

        const totalDelta = showDeltas ? formatPercent(totalDeltaRaw) : null
        const costDelta = showDeltas ? formatPercent(costDeltaRaw) : null
        const tokensDelta = showDeltas ? formatPercent(tokensDeltaRaw) : null
        const ratingDelta = showDeltas ? formatPercent(ratingDeltaRaw) : null

        const priorLabel = 'vs prior period'

        const trendForChart = d.monthlyTrend.map((p) => ({
          name: p.month,
          value: Math.round(p.cost / 100),
        }))

        const priorTrendForChart = prior?.monthlyTrend.map((p) => ({
          name: p.month,
          value: Math.round(p.cost / 100),
        }))

        // Monthly cost chart empty state: show only when 2+ data points exist
        const hasEnoughTrendData = trendForChart.length >= 2

        return (
          <div className="space-y-6">
            {/* KPIs */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Generations"
                value={kpis.total}
                subtextLabel={totalDelta ? priorLabel : 'total AI calls'}
                icon={Wand2}
                trend={trendOf(totalDeltaRaw)}
                index={0}
                {...(totalDelta !== null ? { delta: totalDelta } : {})}
              />
              <KpiCard
                label="Total Cost"
                value={formatCurrency(kpis.totalCost)}
                subtextLabel={costDelta ? priorLabel : 'charged to studio'}
                icon={DollarSign}
                trend={trendOf(costDeltaRaw)}
                index={1}
                {...(costDelta !== null ? { delta: costDelta } : {})}
              />
              <KpiCard
                label="Tokens Used"
                value={kpis.totalTokens.toLocaleString()}
                subtextLabel={tokensDelta ? priorLabel : 'input + output'}
                icon={Wand2}
                trend={trendOf(tokensDeltaRaw)}
                index={2}
                {...(tokensDelta !== null ? { delta: tokensDelta } : {})}
              />
              <KpiCard
                label="Avg Rating"
                value={kpis.avgRating != null ? `${kpis.avgRating.toFixed(1)} / 5` : 'No ratings'}
                subtextLabel={ratingDelta ? priorLabel : 'user satisfaction'}
                icon={Star}
                trend={trendOf(ratingDeltaRaw)}
                index={3}
                {...(ratingDelta !== null ? { delta: ratingDelta } : {})}
              />
            </div>

            {/* Monthly cost trend — empty state when < 2 data points to avoid broken single-bar */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Monthly AI Cost ($)</CardTitle>
              </CardHeader>
              <CardContent>
                {hasEnoughTrendData ? (
                  <RechartsBarChart
                    data={trendForChart}
                    dataKey="value"
                    label="Cost ($)"
                    formatValue={(v) => `$${v}`}
                    {...(priorTrendForChart ? { priorData: priorTrendForChart, priorLabel } : {})}
                  />
                ) : (
                  <EmptyState
                    icon={Wand2}
                    variant="coming-soon"
                    title="Awaiting more data"
                    description="Add another month of usage to see the trend."
                  />
                )}
              </CardContent>
            </Card>

            {/* Model breakdown */}
            {d.modelBreakdown.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Model Breakdown</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.modelBreakdown
                      .sort((a, b) => b.cost - a.cost)
                      .map((m) => (
                        <div key={m.model} className="flex items-center gap-4 px-6 py-4">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium font-mono truncate">{m.model}</p>
                            <p className="text-xs text-muted-foreground">{m.count} generations</p>
                          </div>
                          <div className="text-right shrink-0">
                            <p className="text-sm font-semibold tabular-nums">{formatCurrency(m.cost)}</p>
                            <p className="text-xs text-muted-foreground">total cost</p>
                          </div>
                          <Badge variant="secondary" className="shrink-0 font-mono">
                            {Math.round(m.cost / Math.max(m.count, 1))}¢ avg
                          </Badge>
                        </div>
                      ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Package, AlertTriangle, DollarSign, BarChart2 } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'

interface CategoryStat {
  name: string
  count: number
  /** Total stock value in cents */
  totalValue: number
}

interface InventoryKpis {
  totalItems: number
  lowStockCount: number
  totalCogsConsumed: number
  stockValueCents: number
}

interface InventoryBlock {
  kpis: InventoryKpis
  categoryBreakdown: CategoryStat[]
}

interface InventoryResponse {
  current: InventoryBlock
  prior?: InventoryBlock
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function InventoryReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<InventoryResponse>({
    queryKey: ['reports', 'inventory', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/inventory?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.categoryBreakdown ?? []).map((c) => ({
      category: c.name,
      items: String(c.count),
      stockValue: formatCurrency(c.totalValue),
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-inventory',
    getRows,
    headers: { category: 'Category', items: 'Items', stockValue: 'Stock Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={3} />}
      emptySlot={
        <EmptyState
          icon={Package}
          title="No inventory data yet"
          description="Add inventory items to start tracking COGS and category breakdown."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis
        const showDeltas = compare === '1' && priorKpis !== undefined

        // Low stock is an inverse metric: more low-stock = bad → invertTrend
        const lowStockDeltaRaw = computeDelta(kpis.lowStockCount, priorKpis?.lowStockCount)
        const cogsDeltaRaw = computeDelta(kpis.totalCogsConsumed, priorKpis?.totalCogsConsumed)
        const stockValueDeltaRaw = computeDelta(kpis.stockValueCents, priorKpis?.stockValueCents)

        const lowStockDelta = showDeltas ? formatPercent(lowStockDeltaRaw) : null
        const cogsDelta = showDeltas ? formatPercent(cogsDeltaRaw) : null
        const stockValueDelta = showDeltas ? formatPercent(stockValueDeltaRaw) : null

        const priorLabel = 'vs prior period'

        return (
          <div className="space-y-6">
            {/* 4 KPI cards */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Items"
                value={kpis.totalItems}
                subtextLabel="in inventory"
                icon={Package}
                index={0}
              />
              <KpiCard
                label="Low Stock"
                value={kpis.lowStockCount}
                subtextLabel={lowStockDelta ? priorLabel : 'items below threshold'}
                icon={AlertTriangle}
                invertTrend
                trend={kpis.lowStockCount > 0 ? trendOf(lowStockDeltaRaw) : 'neutral'}
                index={1}
                {...(lowStockDelta !== null ? { delta: lowStockDelta } : {})}
              />
              <KpiCard
                label="COGS Consumed"
                value={formatCurrency(kpis.totalCogsConsumed)}
                subtextLabel={cogsDelta ? priorLabel : 'cost of goods used'}
                icon={DollarSign}
                trend={trendOf(cogsDeltaRaw)}
                index={2}
                {...(cogsDelta !== null ? { delta: cogsDelta } : {})}
              />
              <KpiCard
                label="Stock Value"
                value={formatCurrency(kpis.stockValueCents)}
                subtextLabel={stockValueDelta ? priorLabel : 'current inventory value'}
                icon={BarChart2}
                trend={trendOf(stockValueDeltaRaw)}
                index={3}
                {...(stockValueDelta !== null ? { delta: stockValueDelta } : {})}
              />
            </div>

            {/* Category breakdown — totalValue always formatted via formatCurrency (cents → 2 decimals) */}
            {d.categoryBreakdown.length === 0 ? (
              <EmptyState
                icon={Package}
                title="No category data"
                description="Add inventory items to see category breakdown."
              />
            ) : (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Inventory by Category</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.categoryBreakdown
                      .sort((a, b) => b.totalValue - a.totalValue)
                      .map((cat) => (
                        <div key={cat.name} className="flex items-center gap-4 px-6 py-4">
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium truncate">{cat.name}</p>
                            <p className="text-xs text-muted-foreground">{cat.count} items</p>
                          </div>
                          <div className="text-right shrink-0">
                            {/* formatCurrency(cents) → always $X,XXX.XX — no raw toFixed() anywhere */}
                            <p className="text-sm font-semibold tabular-nums">{formatCurrency(cat.totalValue)}</p>
                            <p className="text-xs text-muted-foreground">stock value</p>
                          </div>
                          <Badge variant={cat.count < 3 ? 'destructive' : 'secondary'} className="shrink-0">
                            {cat.count}
                          </Badge>
                        </div>
                      ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { CalendarDays, TrendingDown } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { useExportCsv } from '@/hooks/use-export-csv'
import { BookingsHeatmap } from '@/components/reports/charts/BookingsHeatmap'
import { StatusBreakdownBar } from '@/components/reports/charts/StatusBreakdownBar'
import type { StatusSegment } from '@/components/reports/charts/StatusBreakdownBar'
import { formatPercent, computeDelta } from '@/lib/utils'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface StatusBreakdown {
  completed: number
  no_show: number
  cancelled: number
  pending: number
  confirmed: number
  in_progress: number
  rescheduled: number
  other: number
}

interface BookingsBlock {
  kpis: BookingKpis
  statusBreakdown: StatusBreakdown
  timeline: Array<{ period: string; count: number }>
  heatmap: number[][]
  serviceRanking: Array<{ name: string; count: number }>
}

interface BookingsResponse {
  current: BookingsBlock
  prior?: BookingsBlock
}

function buildStatusSegments(bd: StatusBreakdown): StatusSegment[] {
  return [
    { key: 'completed', label: 'Completed', count: bd.completed, tone: 'success' },
    { key: 'confirmed', label: 'Confirmed', count: bd.confirmed, tone: 'neutral' },
    { key: 'pending', label: 'Pending', count: bd.pending, tone: 'neutral' },
    { key: 'in_progress', label: 'In progress', count: bd.in_progress, tone: 'neutral' },
    { key: 'rescheduled', label: 'Rescheduled', count: bd.rescheduled, tone: 'neutral' },
    { key: 'no_show', label: 'No-show', count: bd.no_show, tone: 'destructive' },
    { key: 'cancelled', label: 'Cancelled', count: bd.cancelled, tone: 'destructive' },
  ]
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function BookingsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<BookingsResponse>({
    queryKey: ['reports', 'bookings', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/bookings?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.timeline ?? []).map((r) => ({
      period: r.period,
      count: String(r.count),
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-bookings',
    getRows,
    headers: { period: 'Period', count: 'Bookings' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      emptySlot={
        <EmptyState
          icon={CalendarDays}
          title="No booking data yet"
          description="Bookings will appear here once your first appointment is completed."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis
        const bd = d.statusBreakdown
        const timelineForChart = d.timeline.map((r) => ({ name: r.period, value: r.count }))

        const completionRate =
          kpis.total > 0 ? Math.round((kpis.completed / kpis.total) * 100) : 0
        const noShowAndCancelled = kpis.noShows + kpis.cancelled
        const combinedRate =
          kpis.total > 0 ? Math.round((noShowAndCancelled / kpis.total) * 100) : 0

        const statusSegments = buildStatusSegments(bd)

        const showDeltas = compare === '1' && priorKpis !== undefined

        const totalDeltaRaw = computeDelta(kpis.total, priorKpis?.total)

        const completionRatePrior = priorKpis && priorKpis.total > 0
          ? Math.round((priorKpis.completed / priorKpis.total) * 100)
          : undefined
        const completionDeltaRaw = completionRatePrior !== undefined
          ? computeDelta(completionRate, completionRatePrior)
          : null

        const noShowPriorRaw = priorKpis ? priorKpis.noShows + priorKpis.cancelled : undefined
        const noShowDeltaRaw = noShowPriorRaw !== undefined
          ? computeDelta(noShowAndCancelled, noShowPriorRaw)
          : null

        const totalDelta = showDeltas ? formatPercent(totalDeltaRaw) : null
        const completionDelta = showDeltas ? formatPercent(completionDeltaRaw) : null
        const noShowDelta = showDeltas ? formatPercent(noShowDeltaRaw) : null

        const priorLabel = 'vs prior period'

        // Prior timeline for dashed overlay when compare=on
        const priorTimelineForChart = prior?.timeline.map((r) => ({
          name: r.period,
          value: r.count,
        }))

        return (
          <div className="space-y-6">
            {/* 3 KPI cards with real deltas when compare=on */}
            <div className="grid gap-4 sm:grid-cols-3">
              <KpiCard
                label="Total Bookings"
                value={kpis.total}
                subtextLabel={totalDelta ? priorLabel : 'in period'}
                icon={CalendarDays}
                trend={trendOf(totalDeltaRaw)}
                index={0}
                {...(totalDelta !== null ? { delta: totalDelta } : {})}
              />
              <KpiCard
                label="Completion Rate"
                value={`${completionRate}%`}
                subtextLabel={completionDelta ? priorLabel : `${kpis.completed} sessions completed`}
                icon={CalendarDays}
                trend={trendOf(completionDeltaRaw)}
                index={1}
                {...(completionDelta !== null ? { delta: completionDelta } : {})}
              />
              <KpiCard
                label="No-show + Cancelled"
                value={noShowAndCancelled}
                subtextLabel={noShowDelta ? priorLabel : `${combinedRate}% of total`}
                icon={TrendingDown}
                invertTrend
                trend={noShowAndCancelled > 0 ? trendOf(noShowDeltaRaw) : 'neutral'}
                accentVar="var(--color-rust)"
                index={2}
                {...(noShowDelta !== null ? { delta: noShowDelta } : {})}
              />
            </div>

            {/* Status breakdown bar — every booking accounted for, sum == total */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Status Breakdown</CardTitle>
              </CardHeader>
              <CardContent>
                <StatusBreakdownBar statuses={statusSegments} total={kpis.total} />
              </CardContent>
            </Card>

            {/* Timeline with prior dashed overlay when compare=on */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Bookings Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                {timelineForChart.length === 0 ? (
                  <EmptyState
                    icon={CalendarDays}
                    title="No booking data yet"
                    description="Bookings will appear here once created."
                  />
                ) : (
                  <RechartsBarChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Bookings"
                    formatValue={(v) => `${v}`}
                    {...(priorTimelineForChart ? { priorData: priorTimelineForChart, priorLabel } : {})}
                  />
                )}
              </CardContent>
            </Card>

            {/* Heatmap — business hours 10-22, 7×13 grid */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">
                  Booking Heatmap — Day × Hour
                </CardTitle>
              </CardHeader>
              <CardContent>
                <BookingsHeatmap data={d.heatmap} />
              </CardContent>
            </Card>

            {/* Service ranking */}
            {d.serviceRanking.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Services by Popularity</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="divide-y divide-border/50">
                    {d.serviceRanking.slice(0, 10).map((svc, i) => (
                      <div key={svc.name} className="flex items-center gap-4 px-6 py-3">
                        <span className="w-5 text-center text-sm font-bold text-muted-foreground tabular-nums">
                          {i + 1}
                        </span>
                        <span className="flex-1 truncate text-sm font-medium">{svc.name}</span>
                        <Badge variant="secondary">{svc.count} bookings</Badge>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

